async function deviceHash(req){const token=req.headers.get('X-Mola-Device')||'';if(!/^[a-f0-9]{64}$/.test(token))return null;const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(token));return Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('')}
