function favoritesFor(orders,products,name){const key=person(name),stats=new Map();for(const o of orders){if(o.status==='cancelled')continue;let items;try{items=JSON.parse(o.items)}catch{continue}if(!Array.isArray(items))continue;for(const i of items){if(!i||person(i.recipient)!==key)continue;const prod=products.find(p=>p.id===i.id);if(!prod)continue;const q=Number.isInteger(i.qty)&&i.qty>0?i.qty:1;let st=stats.get(prod.id);if(!st){st={productId:prod.id,name:prod.name,count:0,sugarCounts:new Map(),sugar:0,milk:'normal',syrup:null,last:''};stats.set(prod.id,st)}st.count+=q;const sugars=Array.isArray(i.sugars)&&i.sugars.length?i.sugars:Array(q).fill(i.sugar);for(const raw of sugars){const sg=Number.isInteger(raw)&&raw>=0?raw:0,c=st.sugarCounts.get(sg)||{n:0,last:''};c.n+=1;if(o.created>=c.last)c.last=o.created;st.sugarCounts.set(sg,c)}if(o.created>=st.last){st.last=o.created;st.milk=i.milk==='lactose_free'&&prod.milk?'lactose_free':'normal';st.syrup=typeof i.syrup==='string'&&i.syrup?i.syrup:null}}}return [...stats.values()].map(st=>{let best=null;for(const [sg,c] of st.sugarCounts)if(!best||c.n>best.n||(c.n===best.n&&c.last>best.last))best={sg,...c};return {productId:st.productId,name:st.name,count:st.count,sugar:best?best.sg:0,milk:st.milk,...(st.syrup?{syrup:st.syrup}:{}),last:st.last}}).sort((a,b)=>b.count-a.count||b.last.localeCompare(a.last)).slice(0,3).map(({last,...f})=>f)}
