function mergeManual(favs,products,pref,syrups=[]){if(!pref)return favs;const prod=pref.coffee?products.find(p=>p.id===pref.coffee||fold(p.name)===fold(pref.coffee)):null;let out=favs.map(f=>({...f}));if(prod){if(out.some(f=>f.productId===prod.id))out.sort((a,b)=>(b.productId===prod.id)-(a.productId===prod.id));else out.unshift({productId:prod.id,name:prod.name,count:0,sugar:0,milk:'normal'})}for(const f of out){if(Number.isInteger(pref.sugar))f.sugar=pref.sugar;if(pref.milk)f.milk=pref.milk;if(pref.syrup&&syrups.some(x=>x.id===pref.syrup))f.syrup=pref.syrup}return out.slice(0,3)}
export async function buildBackup(db){const row=await db.prepare('SELECT data FROM settings WHERE id=1').first();const out={version:1,exportedAt:new Date().toISOString(),settings:row?JSON.parse(row.data):null};for(const t of BACKUP_TABLES){const rows=(await db.prepare('SELECT * FROM '+t).all()).results.map(r=>({...r}));out[t]=t==='orders'?rows.map(o=>{let items=[];try{items=JSON.parse(o.items)}catch{}return {...o,items}}):rows}return out}
