if(got){FX_MEM={...got,fetchedAt:new Date(now).toISOString(),at:now,stale:false};try{if(env.BACKUPS)await env.BACKUPS.set('fx/latest.json',{usdTry:got.usdTry,source:got.source,fetchedAt:FX_MEM.fetchedAt})}catch{}return {usdTry:got.usdTry,source:got.source,fetchedAt:FX_MEM.fetchedAt,stale:false}}
let last=FX_MEM;if(!last&&env.BACKUPS){try{const b=await env.BACKUPS.get('fx/latest.json');if(b&&Number(b.usdTry)>0&&typeof b.fetchedAt==='string')last={usdTry:Number(b.usdTry),source:String(b.source||''),fetchedAt:b.fetchedAt,at:0}}catch{}}
